fix.code:
@Service
class PaymentService {
    public void pay(long walletId, long amount, String merchantId) {   // không có @Transactional
        try {
            paymentTx.debitAndRecord(walletId, amount, merchantId);    // @Transactional ở bean khác
        } finally {
            activityService.touch(walletId);                          // transaction riêng, chạy sau khi lock đã nhả
        }
    }
}

@Service
class ActivityService {
    @Transactional
    public void touch(long walletId) {
        activityDao.upsert(walletId);   // bảng wallet_activity riêng, không đụng dòng wallet
    }
}
